describe.skip('a genuinely low score still blocks — SUPERSEDED: score is telemetry', () => {
  it('THE LIVE HALT: metrolinx at 0.65 BLOCKS — below the 0.7 bar', () => {
    const { code, out } = runGate([story('AMSD-2041', METROLINX)]);
    expect(code, `0.65 passed a 0.7 bar:\n${out}`).not.toBe(0);
    expect(out).toMatch(/0\.65|quality/);
  });

  it('an APPROVED verdict with a low score still blocks — the score means something', () => {
    expect(runGate([story('S1', { verdict: 'approved', qualityScore: 0.3 })]).code).not.toBe(0);
  });

  it('SPEC_REVIEW_MIN_QUALITY moves the bar without touching the engine', () => {
    const s = [story('S1', METROLINX)];
    expect(runGate(s, { SPEC_REVIEW_MIN_QUALITY: '0.6' }).code).toBe(0);
    expect(runGate(s, { SPEC_REVIEW_MIN_QUALITY: '0.9' }).code).not.toBe(0);
  });
});

it.skip('an empty blocking set disables flag-based blocking, leaving quality in force — SUPERSEDED: quality is telemetry; an empty set means the reviewer\'s own severity decides', () => {
  const s = [story('S1', { verdict: 'needs_review', qualityScore: 0.95, flags: [{ flag: 'some_flag', severity: 'blocking' }] })];
  expect(runGate(s, { SPEC_REVIEW_BLOCKING_FLAGS: '' }).code).toBe(0);
  const low = [story('S1', { verdict: 'approved', qualityScore: 0.2, flags: [] })];
  expect(runGate(low, { SPEC_REVIEW_BLOCKING_FLAGS: '' }).code).not.toBe(0);
});

describe.skip('quality score is a threshold, not decoration — SUPERSEDED: it is telemetry now', () => {
  it('an approved verdict BELOW the bar still blocks', () => {
    const { rc } = runGuard([{ verdict: 'approved', qualityScore: 0.3 }]);
    expect(
      rc,
      'a reviewer can approve while scoring the work 0.3 — the score must mean something',
    ).not.toBe(0);
  });

  it('the bar is CONFIGURABLE', () => {
    const low = { SPEC_REVIEW_MIN_QUALITY: '0.2' };
    expect(runGuard([{ verdict: 'approved', qualityScore: 0.3 }], low).rc).toBe(0);
  });

  it('a missing score does not block on its own — absent is not zero', () => {
    expect(
      runGuard([{ verdict: 'approved', qualityScore: null }]).rc,
      'a reviewer that omitted the score would fail every story',
    ).toBe(0);
  });
});

it.skip('a low quality score still blocks — this fix does not weaken the other rule', () => {
  const { code } = runGate(withCheck([], { verdict: 'approved', qualityScore: 0.3, flags: [] }));
  expect(code).not.toBe(0);
});
